import sys
MOD=998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]

    limit = 100000
    spf = list(range(limit + 1))
    for p in range(2, 317):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if spf[p] == p:
            for x in range(p, limit + 1, p):
                phi[x] -= phi[x] // p

    # weighted[d] = sum(2^(i-1) for earlier i with d | A_i)
    weighted = [0] * (limit + 1)
    answer = 0
    power = 1
    output = []

    for value in values:
        factors = []
        y = value
        while y > 1:
            p = spf[y]
            exponent = 0
            while y % p == 0:
                y //= p
                exponent += 1
            factors.append((p, exponent))

        divisors = [1]
        for p, exponent in factors:
            old = divisors[:]
            multiplier = 1
            for _ in range(exponent):
                multiplier *= p
                divisors.extend(d * multiplier for d in old)

        new_pairs = 0
        for d in divisors:
            new_pairs += phi[d] * weighted[d]
            updated = weighted[d] + power
            weighted[d] = updated - MOD if updated >= MOD else updated

        answer = (2 * answer + new_pairs) % MOD
        output.append(str(answer))
        power = power * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

