import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_y=[[] for _ in range(n+1)]
        m=len(conflictingPairs)
        for i,(a,b) in enumerate(conflictingPairs):
            x,y=sorted((a,b))
            by_y[y].append((x,i))
        heap=[]
        gain=[0]*m
        base=0
        for r in range(1,n+1):
            for x,i in by_y[r]:
                heapq.heappush(heap,(-x,i))
            if heap:
                x=-heap[0][0]
                base+=r-x
                if len(heap)>1:
                    second=-heap[1][0]
                else:
                    second=0
                if x>second:
                    gain[heap[0][1]]+=x-second
            else:
                base+=r
        return base+max(gain)

from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_y=[[] for _ in range(n+1)]
        m=len(conflictingPairs)
        for i,(a,b) in enumerate(conflictingPairs):
            x,y=sorted((a,b))
            by_y[y].append((x,i))
        heap=[]
        gain=[0]*m
        base=0
        for r in range(1,n+1):
            for x,i in by_y[r]:
                heapq.heappush(heap,(-x,i))
            if not heap:
                base+=r
                continue
            first=heapq.heappop(heap)
            x=-first[0]
            base+=r-x
            second=-heap[0][0] if heap else 0
            if x>second:
                gain[first[1]]+=x-second
            heapq.heappush(heap,first)
        return base+max(gain)

