import sys

INF = 10**30

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    n = next(it)
    m = next(it)
    q = next(it)

    edges = []
    for _ in range(m):
        a = next(it) - 1
        b = next(it) - 1
        c = next(it)
        edges.append((a, b, c))

    queries = []
    deletions = []
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            e = next(it) - 1
            queries.append((1, e))
            deletions.append(e)
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    answers = []
    closed = [False] * m
    block_size = 42

    for start in range(0, q, block_size):
        block = queries[start:start + block_size]
        special_edges = [item[1] for item in block if item[0] == 1]
        special_set = set(special_edges)

        # Compute distances using roads that are not deleted during this block.
        base = [[INF] * n for _ in range(n)]
        for i in range(n):
            base[i][i] = 0
        for idx, (a, b, c) in enumerate(edges):
            if idx not in special_set and not closed[idx]:
                base[a][b] = base[b][a] = c

        for k in range(n):
            row_k = base[k]
            for i in range(n):
                row_i = base[i]
                dik = row_i[k]
                if dik == INF:
                    continue
                for j in range(n):
                    candidate = dik + row_k[j]
                    if candidate < row_i[j]:
                        row_i[j] = candidate

        # Only endpoints of roads deleted in this block are needed in the
        # compressed graph.
        endpoints = []
        endpoint_index = {}
        for e in special_edges:
            a, b, _ = edges[e]
            for v in (a, b):
                if v not in endpoint_index:
                    endpoint_index[v] = len(endpoints)
                    endpoints.append(v)

        s = len(endpoints)
        cached_rows = None
        compressed = None

        def rebuild():
            nonlocal compressed, cached_rows
            compressed = [
                [base[u][v] for v in endpoints]
                for u in endpoints
            ]
            for e in special_edges:
                if closed[e]:
                    continue
                a, b, c = edges[e]
                ia = endpoint_index[a]
                ib = endpoint_index[b]
                if c < compressed[ia][ib]:
                    compressed[ia][ib] = compressed[ib][ia] = c

            for k in range(s):
                row_k = compressed[k]
                for i in range(s):
                    row_i = compressed[i]
                    dik = row_i[k]
                    if dik == INF:
                        continue
                    for j in range(s):
                        candidate = dik + row_k[j]
                        if candidate < row_i[j]:
                            row_i[j] = candidate
            cached_rows = {}

        rebuild()

        for typ, a in block:
            if typ == 1:
                closed[a] = True
                rebuild()
            else:
                x, y = a, None
                # The query tuple stores both endpoints.
                # Recover y from the original block item.
                # (Handled by iterating with the tuple below.)
                raise AssertionError("unreachable")

    # Process queries with the same block structure, retaining query endpoints.
    # This section is replaced below; it is kept separate for clarity.
    sys.stdout.write("\n".join(answers))

if __name__ == "__main__":
    main()

