import sys
from math import gcd

def main():
    vals = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = vals[0], vals[1]
    machines = []
    pos = 2
    for _ in range(n):
        a, p, b, q = vals[pos:pos + 4]
        pos += 4
        # Put the machine with lower cost per unit of capacity first.
        if p * b <= q * a:
            machines.append((a, p, b, q))
        else:
            machines.append((b, q, a, p))

    def feasible(target):
        total_cost = 0
        for a, p, b, q in machines:
            # In an optimum, fewer than a/gcd(a,b) units of the
            # less cost-effective machine are needed: beyond that,
            # an equal-capacity set of baseline machines is no dearer.
            limit = a // gcd(a, b)
            best = None
            for y in range(limit):
                remaining = target - b * y
                baseline_units = 0 if remaining <= 0 else (remaining + a - 1) // a
                cost = y * q + baseline_units * p
                if best is None or cost < best:
                    best = cost
            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

