class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Pascal's triangle for choosing the remaining set bits.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # depth[x] is the number of repeated popcount operations needed
        # to reach 1 from x (for x >= 1).
        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            depth[x] = 1 + depth[x.bit_count()]

        ans = 0
        used = 0
        for i, bit in enumerate(s):
            remaining = n - i - 1
            if bit == '1':
                # Make this bit 0, then freely choose the remaining bits.
                for total_ones in range(1, n + 1):
                    if depth[total_ones] <= k - 1:
                        needed = total_ones - used
                        if 0 <= needed <= remaining:
                            ans = (ans + comb[remaining][needed]) % MOD
                used += 1

        return ans

