class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Binomial coefficients up to n.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # Number of popcount operations needed to reach 1.
        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            depth[x] = 1 + depth[x.bit_count()]

        ans = 0
        used = 0
        for i, ch in enumerate(s):
            rem = n - i - 1
            if ch == '1':
                for total in range(1, n + 1):
                    if depth[total] <= k - 1:
                        need = total - used
                        if 0 <= need <= rem:
                            ans += comb[rem][need]
                used += 1
        # The count above represents values with positive popcount; zero not included.
        return ans % MOD

