import sys
from collections import deque

def solve():
    data=sys.stdin.read().split()
    if not data:return
    n=int(data[0]); rows=data[1:]
    # Incoming and outgoing adjacency grouped by label.
    inc=[[[] for _ in range(26)] for _ in range(n)]
    out=[[[] for _ in range(26)] for _ in range(n)]
    dist=[[-1]*n for _ in range(n)]
    q=deque()
    for i in range(n):
        dist[i][i]=0; q.append((i,i))
    for i,row in enumerate(rows):
        for j,ch in enumerate(row):
            if ch!='-':
                c=ord(ch)-97
                out[i][c].append(j); inc[j][c].append(i)
                if dist[i][j]<0:
                    dist[i][j]=1; q.append((i,j))
    while q:
        u,v=q.popleft()
        nd=dist[u][v]+2
        for c in range(26):
            xs=inc[u][c]; ys=out[v][c]
            if not xs or not ys: continue
            for x in xs:
                dx=dist[x]
                for y in ys:
                    if dx[y]<0:
                        dx[y]=nd; q.append((x,y))
    print('\n'.join(' '.join(map(str,r)) for r in dist))

solve()

