import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    u = []
    d = []
    p = 2
    for _ in range(n):
        u.append(data[p])
        d.append(data[p + 1])
        p += 2

    upper = min(a + b for a, b in zip(u, d))

    def feasible(h):
        lo = max(0, h - d[0])
        high = u[0]
        if lo > high:
            return False
        for i in range(1, n):
            lo = max(max(0, h - d[i]), lo - x)
            high = min(u[i], high + x)
            if lo > high:
                return False
        return True

    low = 0
    while low < upper:
        mid = (low + upper + 1) // 2
        if feasible(mid):
            low = mid
        else:
            upper = mid - 1

    print(sum(u) + sum(d) - n * low)

if __name__ == '__main__':
    main()

