# Find the largest d such that d^3 < N.
lo, hi = 0, 1_000_001
while lo < hi:
    mid = (lo + hi + 1) // 2
    if mid**3 < N:
        lo = mid
    else:
        hi = mid - 1

for d in range(1, lo + 1):
    if N % d != 0:
        continue

    # Solve 3d*y^2 + 3d^2*y + d^3 - N = 0.
    disc = 3 * d * (4 * N - d**3)
    root = math.isqrt(disc)
    if root * root != disc:
        continue

    numerator = root - 3 * d * d
    denominator = 6 * d
    if numerator <= 0 or numerator % denominator != 0:
        continue

    y = numerator // denominator
    if d * (3 * y * y + 3 * d * y + d * d) == N:
        print(y + d, y)
        break
else:
    print(-1)

