class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n,m=len(grid),len(grid[0]); N=n*m
        dirs=[(-1,1),(1,1),(1,-1),(-1,-1)]
        S=array('H',[0])*(N*8)
        F=array('H',[0])*(N*8)
        for d,(dr,dc) in enumerate(dirs):
            rows=range(n-1,-1,-1) if dr==1 else range(n)
            nd=(d+1)%4
            for r in rows:
                for c in range(m):
                    i=r*m+c
                    nr,nc=r+dr,c+dc
                    for p,val in ((0,2),(1,0)):
                        k=(i*4+d)*2+p
                        if grid[r][c]==val:
                            z=1
                            if 0<=nr<n and 0<=nc<m:
                                z+=S[((nr*m+nc)*4+d)*2+(p^1)]
                            S[k]=z
                            if 0<=nr<n and 0<=nc<m:
                                a=F[((nr*m+nc)*4+d)*2+(p^1)]
                                b=S[((nr*m+nc)*4+nd)*2+(p^1)]
                                F[k]=1+max(a,b)
