                    ans=max(ans,1)
                    for d,(dr,dc) in enumerate(dirs):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<n and 0<=nc<m:
                            ans=max(ans,1+F[((nr*m+nc)*4+d)*2])
        return ans

