class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        modmask = (1 << k) - 1
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = powers[i] if i == j else (powers[i] + powers[j]) % k
            coeff.append(c)
        dp = [0] * (m + 1)
        dp[m] = 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            mask = 0
            for d in range(10):
                s = d * c % k
                if s == 0:
                    rotated = dp[i + 1]
                else:
                    rotated = ((dp[i + 1] << s) | (dp[i + 1] >> (k - s))) & modmask
                mask |= rotated
            dp[i] = mask
        digits = []
        rem = 0
        for i, c in enumerate(coeff):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (rem - d * c) % k
                if (dp[i + 1] >> need) & 1:
                    digits.append(str(d))
                    rem = need
                    break
        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

