from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next[i] is the first index to the right with nums[next[i]] > nums[i].
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            next_greater[i] = stack[-1] if stack else n
            stack.append(i)

        # Along next-greater links, each value is the prefix maximum until
        # the next link. Store jumps and the sum of those complete ranges.
        levels = n.bit_length()
        jump = [next_greater]
        total = [[nums[i] * (next_greater[i] - i) for i in range(n)]]
        for _ in range(1, levels):
            prev_jump = jump[-1]
            prev_total = total[-1]
            cur_jump = [n] * n
            cur_total = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    cur_jump[i] = prev_jump[mid]
                    cur_total[i] = prev_total[i] + prev_total[mid]
                else:
                    cur_total[i] = prev_total[i]
            jump.append(cur_jump)
            total.append(cur_total)

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        def increment_cost(left: int, right: int) -> int:
            # Sum of the prefix maxima on [left, right] minus the original sum.
            cur = left
            maximum_sum = 0
            for level in range(levels - 1, -1, -1):
                dest = jump[level][cur]
                if dest <= right:
                    maximum_sum += total[level][cur]
                    cur = dest
            maximum_sum += nums[cur] * (right - cur + 1)
            return maximum_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for right in range(n):
            lo, hi = 0, right
            while lo < hi:
                mid = (lo + hi) // 2
                if increment_cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

