from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        nxt=[n]*n
        st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]]<=nums[i]: st.pop()
            nxt[i]=st[-1] if st else n
            st.append(i)
        lg=n.bit_length()
        jump=[nxt]
        agg=[[nums[i]*(nxt[i]-i) for i in range(n)]]
        for _ in range(1,lg):
            pj=jump[-1]; pa=agg[-1]
            nj=[n]*n; na=[0]*n
            for i in range(n):
                mid=pj[i]
                if mid<n:
                    nj[i]=pj[mid]
                    na[i]=pa[i]+pa[mid]
                else: na[i]=pa[i]
            jump.append(nj); agg.append(na)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
        def cost(l,r):
            cur=l; sm=0
            for b in range(lg-1,-1,-1):
                to=jump[b][cur]
                if to<=r:
                    sm+=agg[b][cur]
