from functools import lru_cache
import sys
sys.setrecursionlimit(1000000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    values = data[3:]
    total = n + m + l
    full = (1 << total) - 1
    first = (1 << n) - 1
    second = ((1 << m) - 1) << n

    @lru_cache(None)
    def winning(hand1, hand2, turn):
        hand = hand1 if turn == 0 else hand2
        if not hand:
            return False
        other = hand2 if turn == 0 else hand1

        cards = hand
        while cards:
            bit = cards & -cards
            cards -= bit
            i = bit.bit_length() - 1
            remaining = hand ^ bit
            # The table after playing this card includes the played card.
            table = full & ~(remaining | other)
            # Not taking a card is always allowed.
            if turn == 0:
                if not winning(remaining, other, 1):
                    return True
            else:
                if not winning(other, remaining, 1):
                    return True
            available = table
            while available:
                take = available & -available
                available -= take
                j = take.bit_length() - 1
                if values[j] < values[i]:
                    new_hand = remaining | take
                    if turn == 0:
                        if not winning(new_hand, other, 1):
                            return True
                    else:
                        if not winning(other, new_hand, 1):
                            return True
        return False

    print("Takahashi" if winning(first, second, 0) else "Aoki")

if __name__ == "__main__":
    main()

