def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; a=data[1:]
    vals=sorted(set(a)); m=len(vals)
    rank={v:i+1 for i,v in enumerate(vals)}
    def makebit(): return [0]*(m+1), [0]*(m+1)
    def add(bit, i, d):
        c,s=bit
        v=vals[i-1]
        while i<=m:
            c[i]+=d; s[i]+=d*v; i+=i&-i
    def prefix(bit,i):
        c,s=bit; x=y=0
        while i:
            x+=c[i]; y+=s[i]; i-=i&-i
        return x,y
    def smallest(bit,k):
        if k==0:return 0
        c,s=bit
        idx=cnt=sm=0
        step=1<<(m.bit_length()-1)
        while step:
            ni=idx+step
            if ni<=m and cnt+c[ni]<k:
                idx=ni; cnt+=c[ni]; sm+=s[ni]
            step//=2
        # next coordinate supplies remaining instances
        return sm+(k-cnt)*vals[idx]
    def Fs(seq):
        bit=makebit(); out=[0]*(len(seq)+1); total=0
        for z,v in enumerate(seq,1):
            add(bit,rank[v],1); total+=v
            if z%2==0:
                k=z//2; out[z]=total-2*smallest(bit,k)
