from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Build the same postorder as recursive DFS, without recursion depth risk.
        stack = [(0, False)]
        postorder = []
        while stack:
            v, exiting = stack.pop()
            if exiting:
                postorder.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        position = [0] * n
        for i, v in enumerate(postorder):
            position[v] = i

        subtree_size = [1] * n
        for v in postorder:
            if parent[v] != -1:
                subtree_size[parent[v]] += subtree_size[v]

        text = ''.join(s[v] for v in postorder)

        # Manacher radii for odd-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        # Manacher radii for even-length palindromes; center is between i-1 and i.
        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = []
        for v in range(n):
            end = position[v]
            start = end - subtree_size[v] + 1
            length = subtree_size[v]
            if length % 2:
                is_palindrome = odd[(start + end) // 2] >= length // 2 + 1
            else:
                is_palindrome = even[(start + end + 1) // 2] >= length // 2
            answer.append(is_palindrome)
        return answer

