class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        cnt = Counter(nums)
        for x in sorted(cnt, reverse=True):
            rem = total - x
            if rem % 2 == 0:
                y = rem // 2
                if cnt[y] >= 1 + (x == y):
                    return x
