class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        def feasible(k: int) -> bool:
            # Each index has its own subset-sum choices among covering queries.
            dp = [1] * n  # bit s is set when sum s is attainable
            for l, r, val in queries[:k]:
                shift = val
                for i in range(l, r + 1):
                    dp[i] |= dp[i] << shift
                    dp[i] &= (1 << (nums[i] + 1)) - 1
            return all((dp[i] >> nums[i]) & 1 for i in range(n))

