class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        def is_prime(x):
            if x < 2:
                return False
            d = 2
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 1
            return True

        if is_prime(n) or is_prime(m):
            return -1

        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits - 1

        prime = bytearray(high + 1)
        if high >= 2:
            prime[2:] = b'\x01' * (high - 1)
            for p in range(2, int(high ** 0.5) + 1):
                if prime[p]:
                    count = (high - p * p) // p + 1
                    prime[p * p:high + 1:p] = b'\x00' * count

        places = []
        place = 1
        for _ in range(digits):
            places.append(place)
            place *= 10

        # The cost includes the starting value and each value reached.
        distances = {n: n}
        queue = [(n, n)]
        while queue:
            cost, value = heapq.heappop(queue)
            if distances.get(value) != cost:
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                for change in (-1, 1):
                    new_digit = digit + change
                    if not 0 <= new_digit <= 9:
                        continue
                    nxt = value + change * place
                    if nxt < low or nxt > high or prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < distances.get(nxt, float('inf')):
                        distances[nxt] = new_cost
                        heapq.heappush(queue, (new_cost, nxt))

        return -1

