class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n=len(nums)
        ans=0
        # Z for the suffix beginning at each possible nums2 start.
        for i in range(1,n-1):
            b=nums[i:]
            m=len(b)
            z=[0]*m
            z[0]=m
            left=right=0
            for x in range(1,m):
                if x<=right:
                    z[x]=min(right-x+1,z[x-left])
                while x+z[x]<m and b[z[x]]==b[x+z[x]]:
                    z[x]+=1
                if x+z[x]-1>right:
                    left,right=x,x+z[x]-1
            # prefix condition nums1 prefix nums2; for a fixed i it holds
            # when nums[:i] == nums[i:2*i].
            first=(2*i<=n and nums[:i]==nums[i:2*i])
            # d is the length of nums2; it cannot exceed the remainder.
            for d in range(1,m):
                second=(2*d<=m and z[d]>=d)
                if first and d>=i or second:
                    ans+=1
        return ans

