from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)

        is_target = [False] * n
        for i in targetIndices:
            is_target[i] = True

        inf = n + 1
        # dp[j]: minimum number of target positions used in an embedding
        # of pattern[:j] among the source characters processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = int(is_target[i])
            # Descending order ensures this source character is used at most once.
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] != inf:
                    dp[j + 1] = min(dp[j + 1], dp[j] + cost)

        return len(targetIndices) - dp[m]

