import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse each edge so paths outward from 0 correspond to paths toward 0.
        reverse_graph = [[] for _ in range(n)]
        for a, b, weight in edges:
            reverse_graph[b].append((a, weight))

        inf = float('inf')
        best = [inf] * n
        best[0] = 0
        heap = [(0, 0)]

        while heap:
            cost, node = heapq.heappop(heap)
            if cost != best[node]:
                continue
            for prev, weight in reverse_graph[node]:
                new_cost = max(cost, weight)
                if new_cost < best[prev]:
                    best[prev] = new_cost
                    heapq.heappush(heap, (new_cost, prev))

        answer = max(best)
        return -1 if answer == inf else answer

