class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state gives the colors of a mirrored pair: (left, right).
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Process mirrored pairs from the two ends toward the center.
        for i in range(1, n // 2):
            ndp = [10**30] * len(states)
            for cur, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                for prev, (p, q) in enumerate(states):
                    if a != p and b != q:
                        ndp[cur] = min(ndp[cur], dp[prev] + pair_cost)
            dp = ndp

        return min(dp)

