class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j
        m = len(runs)
        pref = [0] * (m + 1)
        for i, (ch, length) in enumerate(runs):
            pref[i + 1] = max(pref[i], length if ch == '0' else 0)
        suff = [0] * (m + 1)
        for i in range(m - 1, -1, -1):
            ch, length = runs[i]
            suff[i] = max(suff[i + 1], length if ch == '0' else 0)
        best = 0
        for k in range(1, m - 1):
            if runs[k][0] == '1' and runs[k-1][0] == '0' and runs[k+1][0] == '0':
                b = runs[k][1]
                adjacent = runs[k-1][1] + runs[k+1][1]
                other = max(pref[k-1], suff[k+2])
                best = max(best, adjacent, other - b)
        return s.count('1') + best

