class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowel_index = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}
        n = len(word)
        total = 0

        for left in range(n):
            mask = 0
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                index = vowel_index.get(ch)
                if index is None:
                    consonants += 1
                    if consonants > k:
                        break
                else:
                    mask |= 1 << index

                if consonants == k and mask == 31:
                    total += 1

        return total

